package WhisperMode::Runtime;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use WhisperMode::Artifacts;
use WhisperMode::Audio;
use WhisperMode::Config;
use WhisperMode::Logger qw(log_msg);
use WhisperMode::Memory;
use WhisperMode::Recorder;
use WhisperMode::State;
use WhisperMode::Systemd;
use WhisperMode::Transcriber;

has config => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Config->new() } );
has state => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::State->new() } );
has artifacts => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Artifacts->new() } );
has audio => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Audio->new() } );
has systemd => ( is => 'ro', lazy => 1, builder => sub { WhisperMode::Systemd->new() } );

sub _recorder {
    my ($self) = @_;
    return WhisperMode::Recorder->new(
        artifacts => $self->artifacts(), audio => $self->audio(),
        state => $self->state(), systemd => $self->systemd(),
    );
}

sub _memory {
    my ($self) = @_;
    return WhisperMode::Memory->new(config => $self->config(), systemd => $self->systemd());
}

sub run {
    my ($self, $action) = @_;
    if ($action eq 'server-enabled') {
        $self->_memory()->enabled() or die "whisper-record-toggle: WHISPER_PERSISTENT_MEM is disabled\n";
        return 0;
    }
    if ($action eq 'server') {
        $self->_memory()->run_server();
        return 0;
    }
    if ($action eq 'record-worker') {
        my $lock = $self->state()->lock(0, 0);
        $self->_recorder()->record_worker();
        return 0;
    }
    if ($action eq 'transcribe') {
        my $lock = $self->state()->lock(0, 0);
        WhisperMode::Transcriber->new(
            artifacts => $self->artifacts(), config => $self->config(),
            memory => $self->_memory(), state => $self->state(),
        )->transcribe_pending();
        return 0;
    }
    if ($action eq 'mute-default-source') {
        my $lock = $self->state()->lock(0, 1);
        return 0 if !$lock;
        return 0 if $self->systemd()->is_active($self->systemd()->record_service());
        $self->audio()->set_default_source_muted(1);
        return 0;
    }

    my $lock = $self->state()->lock(0, 0);
    my $recorder = $self->_recorder();
    my $pending = $self->state()->read();
    my $transcribe = 0;
    if ($action eq 'toggle') {
        if ($self->systemd()->is_active($self->systemd()->record_service()) || $pending) {
            $transcribe = defined $recorder->stop();
        } else {
            $recorder->start();
        }
    } elsif ($action eq 'start') {
        $recorder->start();
    } elsif ($action eq 'stop') {
        $transcribe = defined $recorder->stop();
    } else {
        die "whisper-record-toggle: unsupported action: $action\n";
    }
    undef $lock;
    $self->systemd()->start_transcription() if $transcribe;
    return 0;
}

1;

--- d-i/forky/hooks/role/desktop/target/usr/local/lib/perl5/site_perl/whisper/WhisperMode/Systemd.pm:1-200 ---
package WhisperMode::Systemd;

use strict;
use warnings;

use Moo;
use MooX::StrictConstructor;
use MooX::TypeTiny;
use Time::HiRes qw(sleep);

has record_service     => ( is => 'ro', default => sub { 'whisper-record.service' } );
has transcribe_service => ( is => 'ro', default => sub { 'whisper-transcribe.service' } );
has server_service     => ( is => 'ro', default => sub { 'whisper-server.service' } );

sub _fatal {
    my ($message) = @_;
    die "whisper-record-toggle: $message\n";
}

sub _run {
    my ($self, @arguments) = @_;
    my $systemctl = '/usr/bin/systemctl';
    -x $systemctl && -f $systemctl or _fatal('systemctl is unavailable');
    return system { $systemctl } $systemctl, '--user', @arguments;
}

sub _detail {
    my ($status) = @_;
    return "exec error: $!" if $status == -1;
    return 'terminated by signal ' . ($status & 127) if $status & 127;
    return 'exit status ' . ($status >> 8);
}

sub is_active { my ($self, $service) = @_; return $self->_run('--quiet', 'is-active', $service) == 0; }
sub is_failed { my ($self, $service) = @_; return $self->_run('--quiet', 'is-failed', $service) == 0; }

sub start_recording {
    my ($self) = @_;
    $self->_run('reset-failed', $self->record_service());
    my $status = $self->_run('start', $self->record_service());
    return if $status == 0 && $self->wait_active($self->record_service(), 50);
    _fatal('cannot start recording service: ' . _detail($status));
}

sub stop_recording {
    my ($self) = @_;
    return if !$self->is_active($self->record_service());
    my $status = $self->_run('stop', $self->record_service());
    $status == 0 or _fatal('cannot stop recording service: ' . _detail($status));
    $self->wait_inactive($self->record_service(), 150)
        or _fatal('recording service did not stop within 15 seconds');
}

sub start_transcription {
    my ($self) = @_;
    my $status = $self->_run('--no-block', 'start', $self->transcribe_service());
    $status == 0 or _fatal('cannot start transcription service: ' . _detail($status));
}

sub wait_active {
    my ($self, $service, $attempts) = @_;
    for (1 .. $attempts) {
        return 1 if $self->is_active($service);
        return 0 if $self->is_failed($service);
        sleep 0.1;
    }
    return 0;
}

sub wait_inactive {
    my ($self, $service, $attempts) = @_;
    for (1 .. $attempts) {
        return 1 if !$self->is_active($service);
        sleep 0.1;
    }
    return 0;
}

1;

