   grep -Fqx 'Wants=pipewire-pulse.service wireplumber.service' "$MUTE_DEFAULT_UNIT" &&
   grep -Fqx 'After=labwc-session.target pipewire-pulse.service wireplumber.service' "$MUTE_DEFAULT_UNIT" &&
   grep -Fqx 'ExecStart=/usr/local/libexec/whisper-record-toggle mute-default-source' "$MUTE_DEFAULT_UNIT" &&
   grep -Fqx 'WantedBy=labwc-session.target' "$MUTE_DEFAULT_UNIT" &&
   assert_contains 'etc/systemd/user/whisper-mute-default.service /etc/systemd/user/whisper-mute-default.service 0644' "$DESKTOP_COMPONENTS" &&
   assert_contains 'unit=whisper-mute-default.service' "$DESKTOP_COMPONENTS"; then
  pass "the Whisper addon explicitly mutes the default microphone when the Labwc session starts"
else
  fail "the Whisper addon explicitly mutes the default microphone when the Labwc session starts"
fi

